package in.industrend.social;import com.fasterxml.jackson.databind.*;import jakarta.servlet.http.Cookie;import java.net.URI;import java.net.http.*;import java.util.*;import org.springframework.beans.factory.annotation.Value;import org.springframework.stereotype.Component;@Component class AdminAuthorizer{private final HttpClient http=HttpClient.newHttpClient();private final ObjectMapper json;private final String identity,token;AdminAuthorizer(ObjectMapper json,@Value("${services.identity.url}")String identity,@Value("${services.internal-token}")String token){this.json=json;this.identity=identity;this.token=token;}UUID require(Cookie[]cookies){var session=Arrays.stream(cookies==null?new Cookie[0]:cookies).filter(c->"IT_ADMIN_SESSION".equals(c.getName())).map(Cookie::getValue).findFirst().orElse("");try{var request=HttpRequest.newBuilder(URI.create(identity+"/internal/v1/admin/validate")).header("X-Service-Token",token).header("X-Admin-Session",session).GET().build();var response=http.send(request,HttpResponse.BodyHandlers.ofString());if(response.statusCode()!=200)throw new IllegalArgumentException("Admin authentication required");return UUID.fromString(json.readTree(response.body()).get("adminUserId").asText());}catch(InterruptedException e){Thread.currentThread().interrupt();throw new IllegalStateException("Authentication interrupted",e);}catch(Exception e){throw new IllegalArgumentException("Admin authentication required");}}}
